import {Component, HostBinding, OnInit} from '@angular/core';
import {Router} from '@angular/router';
import {endOfDay, subDays} from 'date-fns';
import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {HttpClientService} from '../../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from '../../../environments/environment';
import {DatePipe} from '@angular/common';

const { Ocr } = Plugins;
@Component({
    selector: 'app-collection-statistics',
    templateUrl: 'collection-statistics.page.html',
    styleUrls: ['collection-statistics.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class CollectionStatisticsPage implements OnInit {
    collectNumByUseList = [];
    totalPatientNum;
    totalTubeNum;
    SelectTime = 5;
    beginDate = endOfDay(subDays(new Date(), 4));
    endDate = endOfDay(new Date());
    timeList = [
        {id: 5, name: '5日内记录 '},
        {id: 6, name: '6日内记录 '},
        {id: 7, name: '7日内记录 '},
        {id: 8, name: '8日内记录 '},
        {id: 9, name: '9日内记录 '},
        {id: 10, name: '10日内记录 '},
        {id: 11, name: '11日内记录 '},
        {id: 12, name: '12日内记录 '},
        {id: 13, name: '13日内记录 '},
        {id: 14, name: '14日内记录 '},
        {id: 15, name: '15日内记录 '},
    ];
    selectPersonnelType =  '个人';
    userCollectDayNumList = [];
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private platform: Platform,
        private datePipe: DatePipe,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
        this.selectPersonnelType =  '个人';
        this.getCollectNumByUser();
    }

    // 路由返回
    routeBack() {
       // this.router.navigate(['/BoxList']);
         this.router.navigate(['/tabs/tab1']);
    }
    changeTime(){
        this.beginDate = endOfDay(subDays(new Date(), this.SelectTime - 1));
        if (this.selectPersonnelType === '个人'){
            this.getCollectNumByUser();
        } else {
            this.listUserCollectDayNum();
        }
    }

    changePersonType(value){
        this.selectPersonnelType = value;
        if (value === '个人'){
            this.getCollectNumByUser();
        } else {
            this.listUserCollectDayNum();
        }
    }
    // 调用后台接口
    // 根据采集员查询采集相关数量
    getCollectNumByUser(){
        this.collectNumByUseList = [];
        const condition = {
            "beginDate": this.beginDate,
            "endDate": this.endDate
        };
        this.http
            .post(`rcp/api/box/operate/getCollectNumByUser`, condition , '根据采集员查询采集相关数量', '根据采集员查询采集相关数量失败', {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                 this.collectNumByUseList = data['data']['dayCollects'];
                 this.totalTubeNum = data['data']['totalTubeNum'];
                 this.totalPatientNum = data['data']['totalPatientNum'];
               }
            });
    }
    // 查询采集员不同采集点的相关采集数量
    listUserCollectDayNum(){
        this.userCollectDayNumList = [];
        const condition = {
            "beginDate": this.beginDate,
            "endDate": this.endDate
        };
        this.http
            .post(`rcp/api/box/operate/listUserCollectDayNum`, condition , '查询采集员不同采集点的相关采集数量', '查询采集员不同采集点的相关采集数量失败', {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                    this.userCollectDayNumList = data['data'];
                }
            });
    }
}
